        Set<Cell> next = new LinkedHashSet<>();
        for (Cell cell : population.candidates()) {
            if (isAliveNextGeneration(cell, population)) {
                next.add(cell);
            }
        }
        return next;
    }

    private boolean isAliveNextGeneration(Cell cell, Population population) {
        int livingNeighbours = population.countLivingNeighbours(cell);
        return population.isAlive(cell)
